/// <summary>
/// designed from AVA
/// </summary>
/// <returns>AVAMSQQueueId</returns>
public AVAMSQQueueId sendSalesConfirmation()
{
    AVAMSQQueueId avaMSQQueueId;

    avaMSQQueueId = next sendSalesConfirmation();
    SalesOriginId   originId = custConfirmJour.salesTable().SalesOriginId;
    if (!avaMSQQueueId)
    {
        if (custConfirmJour.RecId)
        {
            if (originId != '')
            {
                avaMSQQueueId = AVAMSQProcessingQueue::uploadExportFromProcessTOS(AVAMSQOutIntProcesses::AVAEDISalesOrderConfirmationOut,
                                                                                   int642Str(custConfirmJour.RecId),
                                                                                   CustVendACType::Cust,
                                                                                   custConfirmJour.OrderAccount, '','',
                                                                                   custConfirmJour.ConfirmDocNum,
                                                                                   custConfirmJour.ConfirmAmount,               ///18.01.2023
                                                                                   originId); ///18-01.2023


                if (avaMSQQueueId)
                {
                    info(strFmt("@AVAEDI:EDITransferToMSQ", AVAMSQOutIntProcesses::AVAEDISalesOrderConfirmationOut, custConfirmJour.ConfirmId, avaMSQQueueId));
                }
            }

            avaMSQQueueId = '';
            avaMSQQueueId = AVAMSQProcessingQueue::uploadExportFromProcessTOS(AVAMSQOutIntProcesses::AVAEDISalesOrderConfirmationOut,
                                                   int642Str(custConfirmJour.RecId),
                                                   CustVendACType::Cust,
                                                   custConfirmJour.OrderAccount, '','',
                                                   custConfirmJour.ConfirmDocNum,
                                                   custConfirmJour.ConfirmAmount,               ///18.01.2023
                                                   ''); ///18-01.2023


            if (avaMSQQueueId)
            {
                info(strFmt("@AVAEDI:EDITransferToMSQ", AVAMSQOutIntProcesses::AVAEDISalesOrderConfirmationOut, custConfirmJour.ConfirmId, avaMSQQueueId));
            }
        }
    }

    return avaMSQQueueId;
}
